export function safeName(value) {
	if (typeof value !== 'string') {
		throw new TypeError('safeName expects a string');
	}

	if (value.includes('..')) {
		throw new Error(`safeName rejected unsafe value: ${value}`);
	}

	return value;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';

import { safeName } from './path.mjs';

// ACC-1 (mandatory): safeName must throw for values containing `..`.
test('throws for values containing ..', () => {
	const unsafe = [
		'..',
		'../etc/passwd',
		'foo/../bar',
		'foo..bar',
		'....',
		'nested/dir/../../escape',
	];

	for (const value of unsafe) {
		assert.throws(() => safeName(value), /unsafe value/, `expected throw for ${value}`);
	}
});

test('returns values without ..', () => {
	for (const value of ['foo', 'foo.bar', 'a.b.c', 'dir/file.txt', '']) {
		assert.equal(safeName(value), value);
	}
});

test('throws for non-string input', () => {
	for (const value of [undefined, null, 42, {}, ['..']]) {
		assert.throws(() => safeName(value), TypeError);
	}
});

